"""Shared argument checking and range bookkeeping for :mod:`wsparse`.

Nothing in here talks to the operating system; it is the part of the module
that is the same no matter which platform layer ends up doing the work.
"""

import os

from .errors import WSParseError


def as_path(path):
    """Normalise ``path`` into a string, rejecting unusable arguments."""
    try:
        return os.fspath(path)
    except TypeError as exc:
        raise WSParseError(
            "path must be a string or os.PathLike, got %r" % (path,), kind="badarg"
        ) from exc


def check_size(size):
    """Reject sizes that cannot describe a file length."""
    if isinstance(size, bool) or not isinstance(size, int):
        raise WSParseError("size must be an integer, got %r" % (size,), kind="badarg")
    if size < 0:
        raise WSParseError("size must not be negative, got %r" % (size,), kind="badarg")


def require_existing(path):
    """Raise a ``kind="os"`` error when ``path`` is not there at all."""
    if not os.path.lexists(path):
        raise WSParseError("no such file: %s" % path, kind="os", path=path)


def require_sparse_capable_object(path):
    """Reject objects that can never carry sparse-file semantics.

    A directory is the common case: it is a perfectly valid path, it just is
    not a stream that can have holes punched in it.  That is an
    ``"unsupported"`` condition, not an I/O error, and it has to be reported as
    one instead of silently succeeding.
    """
    if os.path.isdir(path):
        raise WSParseError(
            "sparse-file operations are not supported on a directory",
            kind="unsupported",
            path=path,
        )


def round_up(value, unit):
    """Round ``value`` up to the next multiple of ``unit``."""
    if unit <= 0 or value <= 0:
        return max(value, 0)
    remainder = value % unit
    if remainder == 0:
        return value
    return value + (unit - remainder)


def normalize_ranges(ranges, size):
    """Clean up the raw ranges reported by the platform layer.

    The result is ordered by offset, free of overlaps and of empty entries, and
    entirely inside ``size``.  Ranges that touch are merged so that a dense
    file comes back as a single range covering the whole file.
    """
    if size <= 0:
        return []
    clipped = []
    for offset, length in ranges:
        offset = int(offset)
        length = int(length)
        if length <= 0:
            continue
        start = max(offset, 0)
        end = min(offset + length, size)
        if end <= start:
            continue
        clipped.append((start, end))
    clipped.sort()

    merged = []
    for start, end in clipped:
        if merged and start <= merged[-1][1]:
            previous_start, previous_end = merged[-1]
            if end > previous_end:
                merged[-1] = (previous_start, end)
        else:
            merged.append((start, end))
    return [(start, end - start) for start, end in merged]

"""Development-time fallback for platforms that are not Windows.

The target platform of :mod:`wsparse` is Windows on NTFS, and the acceptance
criteria are stated in terms of NTFS cluster allocation.  This module exists
only so that the module can be imported and smoke-tested on a developer
workstation that is not Windows; it is *not* an alternative implementation of
the contract and it is never reached on the target platform.
"""

import os

from ._common import normalize_ranges, round_up

#: st_blocks is reported in 512-byte units by POSIX, regardless of the real
#: block size of the file system.
_STAT_BLOCK = 512

_DEFAULT_CLUSTER = 4096


def cluster_size(path):
    try:
        info = os.statvfs(path if os.path.exists(path) else os.path.dirname(path) or ".")
    except (OSError, AttributeError):
        return _DEFAULT_CLUSTER
    size = getattr(info, "f_frsize", 0) or getattr(info, "f_bsize", 0)
    return size or _DEFAULT_CLUSTER


def preallocate(path, size):
    flags = os.O_RDWR | os.O_CREAT
    fd = os.open(path, flags, 0o666)
    try:
        current = os.fstat(fd).st_size
        if size > current:
            os.ftruncate(fd, size)
            current = size
        return current
    finally:
        os.close(fd)


def disk_usage(path):
    info = os.stat(path)
    used = int(getattr(info, "st_blocks", 0)) * _STAT_BLOCK
    if used == 0 and info.st_size > 0:
        used = round_up(info.st_size, cluster_size(path))
    return used


def allocated_ranges(path):
    size = os.path.getsize(path)
    if size == 0:
        return []
    seek_data = getattr(os, "SEEK_DATA", None)
    seek_hole = getattr(os, "SEEK_HOLE", None)
    if seek_data is None or seek_hole is None:
        return [(0, size)]
    found = []
    fd = os.open(path, os.O_RDONLY)
    try:
        cursor = 0
        while cursor < size:
            try:
                start = os.lseek(fd, cursor, seek_data)
            except OSError:
                break
            if start >= size:
                break
            end = os.lseek(fd, start, seek_hole)
            if end <= start:
                break
            found.append((start, min(end, size) - start))
            cursor = end
    finally:
        os.close(fd)
    return normalize_ranges(found, size)


def sparse_state(path):
    info = os.stat(path)
    if info.st_size == 0:
        return False
    allocated = int(getattr(info, "st_blocks", 0)) * _STAT_BLOCK
    return allocated < round_up(info.st_size, cluster_size(path))

"""Allocated-range reporting for sink files.

``FSCTL_QUERY_ALLOCATED_RANGES`` is the only thing on NTFS that knows which
byte ranges of a file are backed by clusters.  Returning ``[(0, size)]`` for
every file -- the old behaviour -- told the transfer layer that a freshly
pre-allocated sink was already complete, which is what broke resume.
"""

from . import _winapi as win
from ._common import as_path, normalize_ranges, require_existing
from .errors import WSParseError, from_oserror


def _allocated_ranges_windows(path):
    try:
        handle = win.open_for_query(path)
    except OSError as exc:
        raise from_oserror(exc, path=path) from exc

    with handle:
        try:
            if win.is_directory(handle):
                raise WSParseError(
                    "a directory has no allocated byte ranges",
                    kind="unsupported",
                    path=path,
                )
            size = win.file_size(handle)
            if size == 0:
                return []
            sparse = win.is_sparse(handle)
        except OSError as exc:
            raise from_oserror(exc, path=path) from exc

        try:
            found = win.query_allocated_ranges(handle, size)
        except OSError as exc:
            if not sparse:
                # A dense file on a volume without the FSCTL is entirely
                # allocated by definition, so the answer is still exact.
                return [(0, size)]
            raise from_oserror(exc, path=path, fsctl=True) from exc

    if not found and not sparse:
        # Non-sparse files are fully backed; some drivers report nothing for
        # them rather than one covering range.
        return [(0, size)]
    return normalize_ranges(found, size)


def allocated_ranges(path):
    """Return ``[(offset, length), ...]`` of the byte ranges backed by clusters.

    The transfer layer uses this to decide which parts of a sink still have to
    be fetched: a range that is already allocated is on disk, everything else
    is a hole that still needs data.  The list is ordered by ``offset`` and the
    ranges never overlap.  Every range lies inside the file's logical length.

    An all-hole sink reports an empty list; a dense file reports a single range
    covering its whole length.
    """
    path = as_path(path)
    require_existing(path)

    if win.is_windows():
        return _allocated_ranges_windows(path)

    from . import _posix

    try:
        return _posix.allocated_ranges(path)
    except OSError as exc:
        raise from_oserror(exc, path=path) from exc

"""Sparse-attribute handling.

Two things matter here.  The attribute has to be set through
``FSCTL_SET_SPARSE`` rather than merely read back, otherwise the call reports a
success it never performed.  And setting it must stay *non-retroactive*: NTFS
only applies sparse semantics to regions created while the attribute is set, so
flagging a file that has already been extended densely does not -- and must not
appear to -- give back the clusters it already holds.  ``disk_usage`` keeps
reporting the dense occupancy afterwards, which is the honest answer.
"""

from . import _winapi as win
from ._common import as_path, require_existing, require_sparse_capable_object
from .errors import WSParseError, from_oserror


def _sparse_state_windows(path):
    try:
        with win.open_for_query(path) as handle:
            if win.is_directory(handle):
                raise WSParseError(
                    "a directory does not carry the sparse attribute",
                    kind="unsupported",
                    path=path,
                )
            return win.is_sparse(handle)
    except OSError as exc:
        raise from_oserror(exc, path=path) from exc


def sparse_state(path):
    """Return ``True`` when ``path`` currently carries the sparse attribute.

    The attribute is read through an open handle so that a flag set earlier in
    the same session is visible immediately.
    """
    path = as_path(path)
    require_existing(path)

    if win.is_windows():
        return _sparse_state_windows(path)

    require_sparse_capable_object(path)
    from . import _posix

    try:
        return _posix.sparse_state(path)
    except OSError as exc:
        raise from_oserror(exc, path=path) from exc


def _sparse_flag_windows(path, enabled):
    try:
        handle = win.open_for_update(path, create=False)
    except OSError as exc:
        raise from_oserror(exc, path=path) from exc

    with handle:
        try:
            if win.is_directory(handle):
                raise WSParseError(
                    "the sparse attribute cannot be set on a directory",
                    kind="unsupported",
                    path=path,
                )
        except OSError as exc:
            raise from_oserror(exc, path=path) from exc

        try:
            win.set_sparse(handle, enabled)
        except OSError as exc:
            # Clearing the attribute on a file that still contains holes, and
            # setting it on an object or volume without sparse support, both
            # come back from the FSCTL and both mean "not possible here".
            raise from_oserror(exc, path=path, fsctl=True) from exc

        try:
            win.flush(handle)
            # Report what the file system ended up with rather than what was
            # requested; nothing about the already-allocated clusters changes.
            return win.is_sparse(handle)
        except OSError as exc:
            raise from_oserror(exc, path=path) from exc


def sparse_flag(path, enabled=True):
    """Turn the sparse attribute of ``path`` on or off.

    ``enabled`` defaults to ``True``.  Returns the state the file ends up in.

    Setting the flag is not retroactive: clusters that were already allocated
    stay allocated, so a file that was extended densely keeps its occupancy and
    ``disk_usage`` keeps reporting it.  Use :func:`wsparse.preallocate`, which
    sets the flag *before* extending, to get a sparse reservation.

    Raises :class:`~wsparse.WSParseError` with ``kind == "unsupported"`` when
    the object or volume has no sparse-file support, or when the attribute
    cannot be cleared because the file still contains holes.
    """
    path = as_path(path)
    require_existing(path)

    if win.is_windows():
        return _sparse_flag_windows(path, bool(enabled))

    require_sparse_capable_object(path)
    raise WSParseError(
        "the sparse attribute is a Windows file-system concept",
        kind="unsupported",
        path=path,
    )

