"""Allocated-range reporting for sink files.

``FSCTL_QUERY_ALLOCATED_RANGES`` is the only thing on NTFS that knows which
byte ranges of a file are backed by clusters.  Returning ``[(0, size)]`` for
every file -- the old behaviour -- told the transfer layer that a freshly
pre-allocated sink was already complete, which is what broke resume.
"""

from . import _winapi as win
from ._common import as_path, normalize_ranges, require_existing
from .errors import WSParseError, from_oserror


def _open_for_ranges(path):
    """Open ``path`` with the read access FSCTL_QUERY_ALLOCATED_RANGES needs.

    The FSCTL is rejected with ``ERROR_ACCESS_DENIED`` on a handle that only
    carries ``FILE_READ_ATTRIBUTES``, so read access is requested up front.
    ``FILE_FLAG_BACKUP_SEMANTICS`` keeps directories openable, so they can be
    recognised and reported as unsupported rather than as an I/O error.
    """
    return win.open_handle(
        path,
        win.GENERIC_READ,
        win.OPEN_EXISTING,
        win.FILE_FLAG_BACKUP_SEMANTICS,
    )


def _allocated_ranges_windows(path):
    try:
        handle = _open_for_ranges(path)
    except OSError as exc:
        read_error = exc
        # Without read access the extents cannot be queried.  A dense file is
        # still answerable from its metadata alone, so fall back to that and
        # only give up when the file really is sparse.
        try:
            with win.open_for_query(path) as meta:
                if win.is_directory(meta):
                    raise WSParseError(
                        "a directory has no allocated byte ranges",
                        kind="unsupported",
                        path=path,
                    )
                size = win.file_size(meta)
                sparse = win.is_sparse(meta)
        except OSError:
            raise from_oserror(read_error, path=path) from read_error
        if size == 0:
            return []
        if not sparse:
            return [(0, size)]
        raise from_oserror(read_error, path=path) from read_error

    with handle:
        try:
            if win.is_directory(handle):
                raise WSParseError(
                    "a directory has no allocated byte ranges",
                    kind="unsupported",
                    path=path,
                )
            size = win.file_size(handle)
            if size == 0:
                return []
            sparse = win.is_sparse(handle)
        except OSError as exc:
            raise from_oserror(exc, path=path) from exc

        try:
            found = win.query_allocated_ranges(handle, size)
        except OSError as exc:
            if not sparse:
                # A dense file on a volume without the FSCTL is entirely
                # allocated by definition, so the answer is still exact.
                return [(0, size)]
            raise from_oserror(exc, path=path, fsctl=True) from exc

    if not found and not sparse:
        # Non-sparse files are fully backed; some drivers report nothing for
        # them rather than one covering range.
        return [(0, size)]
    return normalize_ranges(found, size)


