"""Disk-usage accounting for sink files.

The quota tracker needs the clusters a sink really holds.  ``os.stat`` reports
the logical length, which for a sparse sink is the number the issue calls a
full-time false alarm: a 64 MiB sink holding 128 KiB of data has to account for
128 KiB.

Three Win32 sources can answer the real question, and they do not always agree
at the same instant: ``GetCompressedFileSizeW`` and the handle's
``AllocationSize`` are both served from file metadata that can still be stale
while a writer's buffers are in flight, whereas ``FSCTL_QUERY_ALLOCATED_RANGES``
walks the extents and reflects what is on disk right away.  All three are
consulted and the largest is returned, so the tracker never under-counts.
"""

from . import _winapi as win
from ._common import as_path, require_existing, round_up
from .errors import WSParseError, from_oserror


def _extent_usage(path, cluster):
    """Sum the allocated extents of ``path``, or ``None`` if unavailable."""
    try:
        with win.open_handle(
            path,
            win.GENERIC_READ,
            win.OPEN_EXISTING,
            win.FILE_FLAG_BACKUP_SEMANTICS,
        ) as handle:
            if win.is_directory(handle):
                return None
            size = win.file_size(handle)
            if size == 0:
                return 0
            if not win.is_sparse(handle):
                # Every cluster of a dense file is allocated, holes included,
                # so the extent walk cannot say anything the length does not.
                return round_up(size, cluster)
            total = 0
            for _, length in win.query_allocated_ranges(handle, size):
                total += round_up(int(length), cluster)
            return total
    except OSError:
        return None


def _metadata_usage(path):
    """Return the occupancy the file-system metadata reports."""
    try:
        return int(win.compressed_file_size(path))
    except OSError as exc:
        metadata_error = exc
    try:
        with win.open_for_query(path) as handle:
            return int(win.allocation_size(handle))
    except OSError:
        raise metadata_error


def _disk_usage_windows(path):
    cluster = win.cluster_size(path)

    try:
        with win.open_for_query(path) as handle:
            if win.is_directory(handle):
                raise WSParseError(
                    "a directory does not have a sparse-file disk usage",
                    kind="unsupported",
                    path=path,
                )
    except OSError as exc:
        raise from_oserror(exc, path=path) from exc

    try:
        metadata = _metadata_usage(path)
    except OSError as exc:
        metadata = None
        metadata_error = exc
    else:
        metadata_error = None

    extents = _extent_usage(path, cluster)

    if metadata is None and extents is None:
        raise from_oserror(metadata_error, path=path) from metadata_error

    candidates = [value for value in (metadata, extents) if value is not None]
    # Occupancy is a whole number of clusters; round up so that the tracker
    # never under-counts a partially filled tail cluster.
    return round_up(max(candidates), cluster)


def disk_usage(path):
    """Return the number of bytes ``path`` occupies on disk.

    This is what the quota tracker subtracts from the volume budget, so it
    describes the space the sink actually holds, not the number of bytes a
    reader would see: a sparse sink reports only its allocated clusters, while
    a dense file of the same logical length reports roughly that length.  The
    value is rounded up to a whole cluster (4096 bytes on a default NTFS
    volume).
    """
    path = as_path(path)
    require_existing(path)

    if win.is_windows():
        return _disk_usage_windows(path)

    from . import _posix

    try:
        return _posix.disk_usage(path)
    except OSError as exc:
        raise from_oserror(exc, path=path) from exc

